package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.ruoyi.medical.persistence.FormalInputFixture.*;import java.util.*;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.*;
final class FormalEvaluationInputCandidatesHttpTest {
 @Test void actualControllerReturnsClosedEnvelopeAndNoStore()throws Exception{try(var f=new FormalInputFixture()){var identities=mock(ApplicationSessionIdentity.class);var service=mock(FormalEvaluationInputService.class);var req=mock(HttpServletRequest.class);var res=mock(HttpServletResponse.class);when(req.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));when(req.getHeaders("X-Context-Revision")).thenReturn(Collections.enumeration(List.of("1")));when(identities.requireCurrent(req,null)).thenReturn(f.subject);var result=f.json.object().put("schema_version","1.0.0").put("purpose",PURPOSE).put("offset","0").putNull("next_offset");result.set("items",f.json.object().arrayNode());when(service.candidates(f.subject,"1",PURPOSE,"0")).thenReturn(result);var c=new FormalEvaluationInputCandidatesController(identities,service,f.json);var response=c.read(req,res,null,PURPOSE,"0");assertEquals(result,response.path("data"));assertEquals("1",response.path("resource_revision").asText());verify(res).setHeader("Cache-Control","no-store");verify(res).setHeader("X-Request-Id",response.path("request_id").asText());}}
 @Test void duplicateHeadersQueryAndGetBodyCannotReachService()throws Exception{try(var f=new FormalInputFixture()){var identities=mock(ApplicationSessionIdentity.class);var service=mock(FormalEvaluationInputService.class);var c=new FormalEvaluationInputCandidatesController(identities,service,f.json);for(int mode=0;mode<3;mode++){var req=mock(HttpServletRequest.class);var res=mock(HttpServletResponse.class);when(req.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(mode==0?List.of("1.0.0","1.0.0"):List.of("1.0.0")));when(req.getHeaders("X-Context-Revision")).thenReturn(Collections.enumeration(List.of("1")));if(mode==1)when(req.getQueryString()).thenReturn("purpose=OTHER");if(mode==2)when(req.getContentLengthLong()).thenReturn(1L);assertThrows(SchemaRejection.class,()->c.read(req,res,null,PURPOSE,"0"));}verifyNoInteractions(service);}}
 @Test void responseContractRejectsForgedEligibilityFields()throws Exception{try(var f=new FormalInputFixture()){var identities=mock(ApplicationSessionIdentity.class);var service=mock(FormalEvaluationInputService.class);var req=mock(HttpServletRequest.class);var res=mock(HttpServletResponse.class);when(req.getHeaders("X-Schema-Version")).thenReturn(Collections.enumeration(List.of("1.0.0")));when(req.getHeaders("X-Context-Revision")).thenReturn(Collections.enumeration(List.of("1")));when(identities.requireCurrent(req,null)).thenReturn(f.subject);var result=f.json.object().put("schema_version","1.0.0").put("purpose",PURPOSE).put("offset","0").putNull("next_offset").put("production_eligible",true);result.set("items",f.json.object().arrayNode());when(service.candidates(f.subject,"1",PURPOSE,"0")).thenReturn(result);var c=new FormalEvaluationInputCandidatesController(identities,service,f.json);assertThrows(TenantAccessException.class,()->c.read(req,res,null,PURPOSE,"0"));}}
 @Test void mapperStatementIsBoundedParameterizedAndTenantScoped()throws Exception{try(var f=new FormalInputFixture()){var config=new org.apache.ibatis.session.Configuration();try(var in=getClass().getResourceAsStream("/medical-mappers/FormalEvaluationInputMapper.xml")){new org.apache.ibatis.builder.xml.XMLMapperBuilder(in,config,"candidate-mapper",config.getSqlFragments()).parse();}var values=new HashMap<String,Object>();values.put("userId",ACTOR);values.put("purpose",PURPOSE);values.put("offset",20);var id="com.ruoyi.medical.persistence.mapper.FormalEvaluationInputMapper.candidateVersions";var sql=config.getMappedStatement(id).getBoundSql(values);assertEquals(List.of("purpose","offset"),sql.getParameterMappings().stream().map(p->p.getProperty()).toList());assertTrue(sql.getSql().contains("LIMIT 21 OFFSET ?"));assertTrue(sql.getSql().contains("s.owner_project_id IS NULL"));f.transaction(()->{TenantScope.requireSubjectParameter(id,values);var guarded=new ProtectedTenantInterceptor().parserSingle(sql.getSql(),null);assertTrue(guarded.contains(TENANT));for(var wrong:List.of(Map.of(),Map.of("userId",id(99))))assertThrows(TenantAccessException.class,()->TenantScope.requireSubjectParameter(id,wrong));return null;});}}
}
